			get: createBodyMeasurementsGetOperation(lazyRequestEffectClient),
			list: createBodyMeasurementsListOperation(lazyRequestEffectClient),
			update: createBodyMeasurementsUpdateOperation(lazyRequestEffectClient),
		},
