export type TrainingSummaryPageLoader<T> = (
	page: number,
	pageSize: number,
	options?: HevyExecutionOptions,
) => Effect.Effect<
	TrainingSummaryPage<T>,
	HevyRequestEffectError | PaginationMismatchError
