		input: TrainingSummaryInput,
		options?: HevyExecutionOptions,
	) => Effect.Effect<
		TrainingSummaryResult,
		| HevyRequestEffectError
		| PaginationMismatchError
		| TrainingSummaryValidationError
	>;
	execute(
